using System.Text.Json.Nodes;
using CthExtract.Gta.Tests.Synth;
using CthExtract.Halo;
using CthExtract.Halo.Tests;

namespace CthExtract.E2E;

/// <summary>
/// Fake game folders for a run of the REAL extractor with its real modules and default options (no injected openers,
/// keys or HTTP). Everything is generated by our own synthetic builders; no game data. What each one can reach:
/// <list type="bullet">
/// <item>Halo: MCC store layout with three junk .map files (no synthetic Halo 3 cache file exists, so Reclaimer refuses
/// them: mesh/stats rows end Failed) and a synthetic FSB5 bank + .fsb.info (the sound rows' filename fallback).</item>
/// <item>GTA: SynthGame with every archive OPEN (the run has no real key: the synthetic AES key is not in the real
/// SHA1 list, and NG needs the real magic.dat), store-root layout: vehicles, siren/horn and star readable.</item>
/// <item>Fortnite: CUE4Parse's own Apache-2.0 UE6.0 fixture containers (only with CTH_REFS; never vendored) plus a
/// seeded offline key cache (the fixture's published AES key and .usmap). The fixture mapping lacks Fortnite's classes,
/// so the module must refuse it and report every row Missing.</item>
/// </list>
/// </summary>
public static class FakeInstalls
{
    public sealed record Made(string Halo, string Gta, string Fortnite, string? FortniteKeysSeed, List<string> Notes);

    public static Made Make(string root)
    {
        root = Path.GetFullPath(root);
        var notes = new List<string>();
        var games = Path.Combine(root, "games");
        if (Directory.Exists(games)) Directory.Delete(games, true);

        // ---- Halo: Steam library layout
        var mcc = Path.Combine(games, "SteamLibrary", "steamapps", "common", "Halo The Master Chief Collection");
        var halo = new SyntheticHalo();
        var audio = SynthAudio.Encode(1, 44100, 0.0f, 0.25);
        var (items, info) = halo.Bank(audio);
        var maps = Path.Combine(mcc, "halo3", "maps");
        Directory.CreateDirectory(maps);
        foreach (var m in new[] { "riverworld", "shared", "guardian" })
            File.WriteAllBytes(Path.Combine(maps, m + ".map"), new byte[16]);
        var fmod = Path.Combine(mcc, "halo3", "fmod", "pc");
        Directory.CreateDirectory(fmod);
        File.WriteAllBytes(Path.Combine(fmod, "sfx.fsb"), SynthAudio.BuildFsb5(items));
        File.WriteAllBytes(Path.Combine(fmod, "sfx.fsb.info"), FsbInfo.Write(info));
        notes.Add($"halo: {mcc} (3 junk .map files, synthetic sfx.fsb with {items.Count} samples)");

        // ---- GTA: store root above the game folder, every archive OPEN, no AES key planted
        using (var g = new SynthGame(new SynthGame.Options
        {
            PlantAesKey = false, BaseEnc = RpfEnc.Open, DlcEnc = RpfEnc.Open, AudioEnc = RpfEnc.Open, TxdEnc = RpfEnc.Open,
            CommonEnc = RpfEnc.Open, UpdateEnc = RpfEnc.Open, SubfolderLayout = true,
        }))
        {
            CopyTree(g.Root, Path.Combine(games, "Rockstar"));
        }
        var gta = Path.Combine(games, "Rockstar");
        notes.Add($"gta: {gta} (store root; synthetic OPEN archives; GTA5.exe without a key)");

        // ---- Fortnite: CUE4Parse fixtures (optional)
        var fn = Path.Combine(games, "Epic Games", "Fortnite");
        string? seed = null;
        if (CthExtract.Fortnite.Tests.Fixtures.Ue60 is not null)
        {
            CthExtract.Fortnite.Tests.Fixtures.MakeInstall(fn);
            seed = Path.Combine(root, "seed", "keys", "fortnite");
            if (Directory.Exists(seed)) Directory.Delete(seed, true);
            Directory.CreateDirectory(seed);
            var usmap = CthExtract.Fortnite.Tests.Fixtures.Usmap();
            File.Copy(usmap, Path.Combine(seed, "fixture.usmap"), true);
            File.WriteAllText(Path.Combine(seed, "fixture_api.fortniteporting.app.json"), new JsonObject
            {
                ["source"] = "https://api.fortniteporting.app/e2e-fixture",
                ["version"] = "6.0",
                ["build"] = null,
                ["mainKey"] = "0x" + CthExtract.Fortnite.Tests.Fixtures.AesKeyHex,
                ["dynamicKeys"] = new JsonArray(),
                ["usmap"] = "fixture.usmap",
                ["usmapUrl"] = null,
                ["usmapMd5"] = null,
                ["fetchedUtc"] = DateTime.UtcNow.ToString("O"),
            }.ToJsonString());
            notes.Add($"fortnite: {fn} (CUE4Parse UE6.0 fixture containers; offline key cache seed {seed})");
        }
        else
        {
            Directory.CreateDirectory(Path.Combine(fn, "FortniteGame", "Content", "Paks"));
            notes.Add($"fortnite: {fn} (empty Paks folder: CUE4Parse fixtures not available, set CTH_REFS)");
        }
        return new Made(mcc, gta, fn, seed, notes);
    }

    public static void CopyTree(string from, string to)
    {
        foreach (var d in Directory.EnumerateDirectories(from, "*", SearchOption.AllDirectories))
            Directory.CreateDirectory(Path.Combine(to, Path.GetRelativePath(from, d)));
        Directory.CreateDirectory(to);
        foreach (var f in Directory.EnumerateFiles(from, "*", SearchOption.AllDirectories))
            File.Copy(f, Path.Combine(to, Path.GetRelativePath(from, f)), true);
    }
}
